// HasAttemptRef applies the HasEdge predicate on the "attempt_ref" edge.
func HasAttemptRef() predicate.OrganizationAttemptEvidence {
	return predicate.OrganizationAttemptEvidence(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AttemptRefTable, AttemptRefColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAttemptRefWith applies the HasEdge predicate on the "attempt_ref" edge with a given conditions (other predicates).
func HasAttemptRefWith(preds ...predicate.OrganizationExecutionAttempt) predicate.OrganizationAttemptEvidence {
	return predicate.OrganizationAttemptEvidence(func(s *sql.Selector) {
		step := newAttemptRefStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

